from pathlib import Path
import re,zipfile,shutil
p=Path('public/index.html');s=p.read_text();sections=re.findall(r'<section\b.*?</section>',s)
def replace(n,name,tool,title,body,scene):
 global s
 old=sections[n-1]
 new=f'<section class="chapter" data-name="{name}" id="chapter-{n}" aria-labelledby="s{n}"><div class="eyebrow">0{n} / {name}</div><div class="layout"><div class="copy"><div class="chapter-tool">{tool}</div><h2 id="s{n}">{title}</h2><p class="body">{body}</p></div>{scene}</div></section>'
 s=s.replace(old,new)
def panel(x):return '<div class="toolscene"><div class="schematic">'+x+'</div></div>'
streets=''.join(f'<div class="street-step"><small>{a}</small><strong>{b}</strong><span>{c}</span></div>' for a,b,c in [('01 / PREFLOP','Two private cards','Choose a starting plan'),('02 / FLOP','Three shared cards','Reassess strength and price'),('03 / TURN','New information','Reconsider the opponent and sizing'),('04 / RIVER','The final decision','Value, pressure, or get out')])
replace(4,'Build a whole hand','RuOS / a full-street working prototype','Poker happens<br><em>across the hand.</em>','A poker player must reconsider decisions as the board changes, the pot grows, and an opponent acts.<br><br>The new RuOS prototype supports <strong>preflop, flop, turn, and river</strong>, legal betting and raises, all-ins, and showdown. A sampled-equity and pot-odds policy supplies decisions. That gives us a full-hand environment in which to develop and test the ten abilities.<br><br><a href="/play/">Open the playable prototype ↗</a>',panel('<div class="stamp">THE DECISION CHANGES WITH THE INFORMATION</div><div class="street-story">'+streets+'</div><p class="proof">Full-street engine: 12 automated tests passed on RuOS.<br>A complete hand also reached showdown in the browser.</p><p class="diagram-note">This is a working play-money prototype. A strong trained poker policy has not been demonstrated.</p>'))
replace(7,'Show the decisions','From the tools to the table / inspect the actual play','Show the hand.<br><em>Explain the choice.</em>','Watch RiverRoo make legal decisions through a full hand. The prototype exposes the board, pot, available actions, and its equity/pot-odds reasoning.<br><br>Then ask the questions that matter: Did he choose a sensible size? Read the opponent? Use position? Know when to change his plan? Those are the ten-attribute tests we need—not a counter of hands dealt.<br><br><a class="play-cta" href="/play/">Take a seat with RiverRoo →</a>',panel('<div class="stamp">PLAYABLE / INSPECTABLE / REPEATABLE</div><h3>A decision you can examine.</h3><div class="toolnode"><strong>Observe</strong><small>Own cards · shared board · pot · public actions</small></div><div class="wire"></div><div class="toolnode"><strong>Decide</strong><small>Sample equity · consider pot odds · choose a legal action</small></div><div class="wire delayed"></div><div class="toolnode"><strong>Review</strong><small>Read the action history · inspect showdown · replay a seed</small></div><p class="diagram-note">The current heuristic is a baseline for further development. Its competitive strength is unproven.</p>'))
replace(8,'What we can build','The RuvNet journey / from an idea to a testable player','A working player.<br><em>A clear next level.</em>','We started with RiverRoo knowing nothing. <strong>RuOS</strong> gave us a lab. <strong>Ruflo</strong> organised the work. <strong>RuvNet Brain</strong> led us to existing poker work. <strong>RuVector</strong> was exercised in a separate reference-memory prototype.<br><br>We now have a playable full-street foundation and the original ten dimensions to guide its development. The next proof is a frozen baseline versus a trained policy, on unseen full hands, with attribute-specific tests.<br><br><strong>Those full-game improvement measurements do not exist yet.</strong> The presentation shows the tools and working foundation honestly.<div class="links"><a href="/play/">Play RiverRoo ↗</a><a href="/final-report.html">Evidence &amp; technical appendix ↗</a><a href="/RiverRoo-Presentation.zip" download>Download story ↓</a></div>',panel('<div class="stamp">WHAT EXISTS / WHAT COMES NEXT</div><div class="toolnode"><span class="state">Working foundation</span><strong>Full-street poker</strong><small>Legal actions · equity/pot odds · showdown · replay</small></div><div class="wire future"></div><div class="toolnode future"><span class="state">Integration remains</span><strong>rUv’s poker expertise</strong><small>Adapt, train, and evaluate the solver-based policy</small></div><div class="wire future"></div><div class="toolnode future"><span class="state">Measurement remains</span><strong>Ten-attribute improvement</strong><small>Same conditions · unseen hands · honest before/after evidence</small></div>'))
s=s.replace('The early learner practised a narrow fold/call task; its hand counter was never a score for these abilities.','The early exercise did not establish full-game skill. These dimensions define the player we are building and how improvement should be assessed.')
s=s.replace('Early learner: coarse hand groups and reward updates.','Early exercise: coarse state groups and reward updates.').replace('Early learner only chooses fold or call.','No measured bluffing capability in the original exercise.')
s=s.replace('The controlled performance comparison comes in the final chapter.','Full-game improvement must be established by new, controlled measurements.')
s=s.replace('v1.3.0','v1.3.1')
s=s.replace('</style>','''.street-step{padding:15px 0 15px 18px;border-left:2px solid #40dfe855;position:relative;margin:0 0 4px}.street-step:before{content:'';position:absolute;left:-5px;top:21px;width:8px;height:8px;background:#5de3e9;border-radius:50%;box-shadow:0 0 15px #40dfe8}.street-step small,.street-step span{display:block;font:11px/1.6 system-ui;color:#99bdcf}.street-step small{color:#edb35f;font-size:9px;letter-spacing:.12em}.street-step strong{display:block;font:24px Georgia;color:#edf6fa;margin:5px 0}.play-cta{display:inline-block;padding:13px 17px;border:1px solid #40dfe877;border-radius:5px;text-decoration:none;color:#7cebf0}.street-step:nth-child(2){animation:line 5s 1s infinite}.street-step:nth-child(3){animation:line 5s 2s infinite}.street-step:nth-child(4){animation:line 5s 3s infinite}.paused .street-step{animation-play-state:paused} </style>''',1)
p.write_text(s)
notes=Path('public/Presenter-Notes.txt');t=notes.read_text().replace('v1.3.0','v1.3.1');t='Presentation focus: full poker decisions, original ten attributes, and RuvNet tooling. The elementary preflop experiment belongs only in the technical appendix; do not present its score as poker strength.\n'+t;notes.write_text(t)
Path('STORY-CONTRACT.md').write_text(Path('STORY-CONTRACT.md').read_text()+'\nOwner correction: elementary preflop results and million-hand counters are not presentation achievements. Keep them in the technical appendix. Main story centers full hands, the ten attributes, the tools, and honest full-game development evidence.\n')
Path('.receipts/story-inline.js').write_text(re.search(r'<script>(.*?)</script>',s,re.S).group(1))
main=s[s.index('<main'):s.index('</main>')]
assert not any(x in main for x in ['48.45','50.83','+2.38','1,020,000','shove/fold','fold/call'])
with zipfile.ZipFile('public/RiverRoo-Presentation.zip','w',zipfile.ZIP_DEFLATED) as z:
 for f in Path('public').rglob('*'):
  if f.is_file() and f.suffix!='.zip' and f.name!='riverroo-character.png':z.write(f,f.relative_to('public'))
shutil.copy2('public/RiverRoo-Presentation.zip',Path.home()/'Documents/RiverRoo/RiverRoo-Presentation.zip')
print('Elementary preflop result removed from main presentation; full-hand story v1.3.1 prepared.')
